import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useSpring, animated, config } from 'react-spring';

const Home = () => {
  const navigate = useNavigate();

  // Fade-in animation for entire Home section
  const fadeIn = useSpring({
    opacity: 1,
    transform: 'translateY(0px)',
    from: { opacity: 0, transform: 'translateY(50px)' },
    config: config.molasses,
  });

  const nameAnimation = useSpring({
    from: { opacity: 0, transform: 'scale(0.5)' },
    to: { opacity: 1, transform: 'scale(1)' },
    config: config.wobbly,
    delay: 300,
  });

  const titleAnimation = useSpring({
    from: { opacity: 0, transform: 'translateX(-50px)' },
    to: { opacity: 1, transform: 'translateX(0)' },
    config: config.gentle,
    delay: 600,
  });

  const subtitleAnimation = useSpring({
    from: { opacity: 0, transform: 'translateX(50px)' },
    to: { opacity: 1, transform: 'translateX(0)' },
    config: config.gentle,
    delay: 900,
  });

  const buttonAnimation = useSpring({
    from: { opacity: 0, transform: 'translateY(20px)' },
    to: { opacity: 1, transform: 'translateY(0)' },
    config: config.gentle,
    delay: 1200,
  });

  const goToProjects = () => {
    navigate('/projects');
  };

  return (
    <animated.div style={fadeIn} className="home-section">
      <animated.h1 style={nameAnimation} className="name">
        HET PATEL
      </animated.h1>

      <animated.h2 style={titleAnimation} className="title">
        FULL-STACK DEVELOPER
       <div>
        GAME DEVELOPER
       </div>
      </animated.h2>


      <animated.p style={subtitleAnimation} className="subtitle">
        3rd Year Computing Science Student at University of Alberta
      </animated.p>

      <animated.div style={buttonAnimation} className="cta-container">
        <button onClick={goToProjects} className="cta-button primary">
          View my projects
        </button>

        <a
  href={process.env.PUBLIC_URL + '/Resume.pdf'}
  download="Het's_Resume.pdf"
  className="cta-button secondary"
  target="_blank"
  rel="noopener noreferrer"
>
  Download Resume
</a>
      </animated.div>
    </animated.div>
  );
};

export default Home;